sp_widget.client_script:
api.controller = function($location) {

    var c = this;


    c.loading = true;

    c.claims = [];


    // =========================================
    // LOAD CLAIMS
    // =========================================

    c.loadClaims = function() {

        c.loading = true;


        c.server.get({

            action: "get_claims"

        }).then(function(response) {

            c.loading = false;


            if (
                response.data.success === true
            ) {

                c.claims =
                    response.data.claims || [];

            } else {

                c.claims = [];

            }

        }, function() {

            c.loading = false;

            c.claims = [];

        });

    };


    // =========================================
    // VIEW CLAIM
    // =========================================

    c.viewClaim = function(sysId) {

        if (!sysId) {

            alert(
                "Claim information is missing."
            );

            return;

        }


        /*
         * Force the complete portal URL.
         *
         * This ensures the Claim sys_id
         * is passed to Track Claim.
         */

        var portalSuffix = "claims";


        var targetUrl =
            "/" +
            portalSuffix +
            "?id=track_claim" +
            "&sys_id=" +
            encodeURIComponent(sysId);


        window.location.href =
            targetUrl;

    };


    // =========================================
    // SUBMIT CLAIM
    // =========================================

    c.submitClaim = function() {

        window.location.href =
            "/claims?id=submit_claim";

    };


    // =========================================
    // INITIAL LOAD
    // =========================================

    c.loadClaims();

};

sp_widget.css:
.my-claims-container {

    max-width: 1200px;

    margin: 0 auto;

    padding: 35px 25px 50px;

    font-family:
        -apple-system,
        BlinkMacSystemFont,
        "Segoe UI",
        Arial,
        sans-serif;

    color: #1f2937;

}


/* ================================
   HEADER
================================ */

.claims-header {

    display: flex;

    align-items: center;

    gap: 18px;

    margin-bottom: 28px;

}


.claims-icon {

    width: 58px;

    height: 58px;

    border-radius: 14px;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 28px;

    background: #eaf4ff;

}


.claims-header h1 {

    margin: 0;

    font-size: 30px;

    font-weight: 700;

    color: #123b63;

}


.claims-header p {

    margin: 6px 0 0;

    font-size: 15px;

    color: #64748b;

}


/* ================================
   CARD
================================ */

.claims-card {

    background: #ffffff;

    border: 1px solid #e2e8f0;

    border-radius: 16px;

    box-shadow:
        0 5px 20px rgba(15, 23, 42, 0.06);

    overflow: hidden;

}


/* ================================
   CARD HEADER
================================ */

.claims-card-header {

    display: flex;

    justify-content: space-between;

    align-items: center;

    padding: 25px 28px;

    border-bottom: 1px solid #e5e7eb;

}


.claims-card-header h2 {

    margin: 0;

    font-size: 20px;

    font-weight: 700;

    color: #123b63;

}


.claims-card-header p {

    margin: 6px 0 0;

    color: #64748b;

    font-size: 14px;

}


.claim-count {

    background: #eaf4ff;

    color: #1261a0;

    padding: 8px 14px;

    border-radius: 20px;

    font-size: 13px;

    font-weight: 600;

}


/* ================================
   TABLE
================================ */

.table-wrapper {

    width: 100%;

    overflow-x: auto;

}


.claims-table {

    width: 100%;

    border-collapse: collapse;

    min-width: 850px;

}


.claims-table th {

    text-align: left;

    padding: 16px 20px;

    background: #f8fafc;

    color: #475569;

    font-size: 13px;

    font-weight: 700;

    border-bottom: 1px solid #e2e8f0;

}


.claims-table td {

    padding: 18px 20px;

    border-bottom: 1px solid #eef2f7;

    font-size: 14px;

    color: #475569;

}


.claims-table tbody tr:hover {

    background: #f8fbff;

}


.claim-number {

    color: #1261a0;

    font-weight: 700;

}


/* ================================
   STATUS
================================ */

.claim-status {

    display: inline-block;

    padding: 6px 12px;

    border-radius: 20px;

    font-size: 12px;

    font-weight: 700;

}


.status-pending {

    background: #fff7df;

    color: #9a6700;

}


.status-approved {

    background: #e8f8ef;

    color: #18794e;

}


.status-rejected {

    background: #fdecec;

    color: #b42318;

}


/* ================================
   VIEW BUTTON
================================ */

.view-btn {

    border: none;

    background: #1261a0;

    color: #ffffff;

    padding: 9px 15px;

    border-radius: 8px;

    font-size: 13px;

    font-weight: 600;

    cursor: pointer;

}


.view-btn:hover {

    background: #0d4f85;

}


.view-btn span {

    margin-left: 5px;

}


/* ================================
   LOADING
================================ */

.loading-container {

    min-height: 220px;

    display: flex;

    flex-direction: column;

    align-items: center;

    justify-content: center;

    color: #64748b;

}


.loading-spinner {

    width: 35px;

    height: 35px;

    border: 4px solid #e2e8f0;

    border-top-color: #1261a0;

    border-radius: 50%;

    animation: spin 0.8s linear infinite;

    margin-bottom: 15px;

}


@keyframes spin {

    from {
        transform: rotate(0deg);
    }

    to {
        transform: rotate(360deg);
    }

}


/* ================================
   EMPTY
================================ */

.empty-card {

    text-align: center;

    padding: 60px 25px;

}


.empty-icon {

    font-size: 50px;

    margin-bottom: 15px;

}


.empty-card h2 {

    margin: 0 0 8px;

    color: #123b63;

    font-size: 22px;

}


.empty-card p {

    margin: 0 0 25px;

    color: #64748b;

}


/* ================================
   SUBMIT BUTTON
================================ */

.submit-claim-btn {

    border: none;

    background: #1261a0;

    color: #ffffff;

    padding: 12px 20px;

    border-radius: 8px;

    font-size: 14px;

    font-weight: 600;

    cursor: pointer;

}


.submit-claim-btn:hover {

    background: #0d4f85;

}


/* ================================
   REFRESH
================================ */

.refresh-section {

    text-align: center;

    margin-top: 22px;

}


.refresh-btn {

    background: #ffffff;

    color: #1261a0;

    border: 1px solid #1261a0;

    padding: 9px 18px;

    border-radius: 8px;

    font-size: 13px;

    font-weight: 600;

    cursor: pointer;

}


.refresh-btn:hover {

    background: #eaf4ff;

}


/* ================================
   MOBILE
================================ */

@media (max-width: 768px) {

    .my-claims-container {

        padding: 25px 15px 40px;

    }


    .claims-header h1 {

        font-size: 25px;

    }


    .claims-card-header {

        flex-direction: column;

        align-items: flex-start;

        gap: 12px;

    }

}

sp_widget.script:
(function() {

    data.success = false;

    data.claims = [];

    data.message = "";


    // =========================================
    // GET CLAIMS
    // =========================================

    if (!input ||
        input.action != "get_claims") {

        return;

    }


    try {

        var claim =
            new GlideRecord(
                "x_snc_insurance_0_claim"
            );


        var userEmail = gs.getUser().getEmail();
        var ph = new GlideRecord("x_snc_insurance_0_policyholder");
        ph.addQuery("email", userEmail);
        ph.setLimit(1);
        ph.query();
        var phSysId = ph.next() ? ph.getUniqueValue() : "invalid";
        claim.addQuery("policyholder", phSysId);


        claim.orderByDesc(
            "sys_created_on"
        );


        claim.query();


        while (claim.next()) {

            data.claims.push({

                sys_id:
                    claim.getUniqueValue(),

                claim_number:
                    claim.getValue(
                        "claim_number"
                    ) || "",

                claim_type:
                    claim.getDisplayValue(
                        "claim_type"
                    ) || "",

                incident_date:
                    claim.getDisplayValue(
                        "incident_date"
                    ) || "",

                claim_amount:
                    claim.getValue(
                        "claim_amount"
                    ) || "0",

                status:
                    claim.getDisplayValue(
                        "status"
                    ) || "Pending"

            });

        }


        data.success = true;


    } catch (e) {

        data.success = false;

        data.message =
            "Unable to load claims: " +
            e.message;

    }

})();
